css:
.capstone-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.capstone-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(26,58,92,0.25);
    text-align: center;
}

.capstone-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.capstone-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1rem;
}

.capstone-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
    font-weight: 600;
}

.capstone-sim-briefing {
    background: linear-gradient(135deg, #fff9e6 0%, #fff3cd 100%);
    border-left: 5px solid #f0ad4e;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.capstone-sim-briefing h4 {
    margin: 0 0 10px 0;
    color: #856404;
    font-size: 1rem;
}

.capstone-sim-briefing #briefingText {
    color: #664d03;
    font-size: 0.95rem;
    line-height: 1.6;
}

.capstone-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.capstone-sim-secondary-cards {
    margin-bottom: 25px;
}

.capstone-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 18px 14px;
    box-shadow: 0 3px 12px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #2c5f8a;
}

.capstone-sim-status-card:hover {
    transform: translateY(-4px);
}

.capstone-sim-card-revenue { border-top-color: #27ae60; }
.capstone-sim-card-share { border-top-color: #8e44ad; }
.capstone-sim-card-cash { border-top-color: #2980b9; }
.capstone-sim-card-income { border-top-color: #e67e22; }
.capstone-sim-card-eps { border-top-color: #16a085; }
.capstone-sim-card-price { border-top-color: #c0392b; }
.capstone-sim-card-debt { border-top-color: #e74c3c; }
.capstone-sim-card-equity { border-top-color: #3498db; }
.capstone-sim-card-brand { border-top-color: #9b59b6; }
.capstone-sim-card-innov { border-top-color: #1abc9c; }
.capstone-sim-card-cap { border-top-color: #7f8c8d; }
.capstone-sim-card-markets { border-top-color: #f39c12; }

.capstone-sim-label {
    color: #777;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.capstone-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #2c3e50;
}

.capstone-sim-controls {
    background: white;
    border-radius: 16px;
    padding: 25px;
    margin-bottom: 25px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.capstone-sim-controls h3 {
    margin: 0 0 20px 0;
    color: #1a3a5c;
    font-size: 1.2rem;
    border-bottom: 2px solid #eef2f7;
    padding-bottom: 10px;
}

.capstone-sim-decision-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
    margin-bottom: 25px;
}

.capstone-sim-decision-group {
    display: flex;
    flex-direction: column;
}

.capstone-sim-decision-group label {
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.capstone-sim-decision-group small {
    color: #888;
    font-size: 0.78rem;
    margin-top: 4px;
}

.capstone-sim-decision-group .form-control {
    border-radius: 8px;
    border: 2px solid #ddd;
    padding: 8px 12px;
    font-size: 1rem;
    transition: border-color 0.2s;
}

.capstone-sim-decision-group .form-control:focus {
    border-color: #2c5f8a;
    box-shadow: 0 0 0 3px rgba(44,95,138,0.15);
}

.capstone-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}

.capstone-sim-btn-row .btn-primary {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    border: none;
    border-radius: 10px;
    padding: 12px 30px;
    font-size: 1rem;
    font-weight: 600;
    box-shadow: 0 4px 12px rgba(26,58,92,0.3);
    transition: transform 0.2s, box-shadow 0.2s;
}

.capstone-sim-btn-row .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(26,58,92,0.4);
}

.capstone-sim-event-log {
    background: linear-gradient(135deg, #fdecea 0%, #f8d7da 100%);
    border-left: 5px solid #dc3545;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.capstone-sim-event-log h4 {
    margin: 0 0 10px 0;
    color: #721c24;
    font-size: 1rem;
}

.capstone-sim-event-log #eventLogText {
    color: #721c24;
    font-size: 0.95rem;
    line-height: 1.6;
}

.capstone-sim-history {
    background: white;
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 25px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
    overflow-x: auto;
}

.capstone-sim-history h4 {
    margin: 0 0 15px 0;
    color: #1a3a5c;
    font-size: 1rem;
}

.capstone-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.capstone-sim-chart-wrapper {
    background: white;
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
    min-height: 300px;
    position: relative;
}

@media (max-width: 768px) {
    .capstone-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .capstone-sim-decision-grid {
        grid-template-columns: 1fr;
    }
    .capstone-sim-charts {
        grid-template-columns: 1fr;
    }
    .capstone-sim-value {
        font-size: 1.2rem;
    }
}

/* ===== Capstone COMPETE 2.0 design layer (EQIL 2026-10-22). Appended; everything below is scoped to .cc ===== */
.capstone-sim-container.cc {
    --cc-bg: #f4f6fa;
    --cc-surface: #ffffff;
    --cc-surface-2: #f8fafc;
    --cc-ink: #0f172a;
    --cc-ink-2: #334155;
    --cc-muted: #526077;
    --cc-line: #e2e8f0;
    --cc-line-2: #cbd5e1;
    --cc-accent: #1d4ed8;
    --cc-accent-ink: #ffffff;
    --cc-accent-soft: #e0e8fd;
    --cc-good: #15803d;
    --cc-good-soft: #dcfce7;
    --cc-bad: #b42318;
    --cc-bad-soft: #fee4e2;
    --cc-warn: #8a5300;
    --cc-warn-soft: #fef3c7;
    --cc-radius: 12px;
    --cc-radius-sm: 8px;
    --cc-s1: 4px; --cc-s2: 8px; --cc-s3: 12px; --cc-s4: 16px; --cc-s5: 24px; --cc-s6: 32px;
    --cc-shadow: 0 1px 2px rgba(15, 23, 42, 0.06), 0 1px 3px rgba(15, 23, 42, 0.04);
    --cc-focus: 0 0 0 3px #ffffff, 0 0 0 5px #1d4ed8;
    background: var(--cc-bg);
    color: var(--cc-ink);
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    font-size: 15px;
    line-height: 1.45;
    padding: var(--cc-s4);
    min-height: 0;
    max-width: 1440px;
    margin: 0 auto;
    box-sizing: border-box;
}
.cc *, .cc *::before, .cc *::after { box-sizing: border-box; }
.cc p, .cc h1, .cc h2, .cc h3, .cc ul, .cc ol, .cc dl, .cc figure { margin: 0; }
.cc [hidden] { display: none !important; }
.cc .cc-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.cc .cc-muted { color: var(--cc-muted); }
.cc .cc-bad { color: var(--cc-bad); font-weight: 600; }

/* header */
.cc .cc-top { display: flex; align-items: center; justify-content: space-between; gap: var(--cc-s4); flex-wrap: wrap; margin-bottom: var(--cc-s3); }
.cc .cc-kicker { font-size: 12px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: var(--cc-accent); }
.cc .cc-top h1 { font-size: 22px; font-weight: 700; letter-spacing: -0.01em; color: var(--cc-ink); }
.cc .cc-progress { display: flex; flex-direction: column; align-items: flex-end; gap: var(--cc-s2); }
.cc .cc-counter { font-size: 14px; color: var(--cc-ink-2); display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.cc .cc-counter strong { font-size: 20px; color: var(--cc-ink); font-variant-numeric: tabular-nums; }
.cc .cc-year { margin-left: var(--cc-s2); padding: 2px 8px; border-radius: 999px; background: var(--cc-accent-soft); color: #1e3a8a; font-size: 12px; font-weight: 600; }
.cc .cc-steps { list-style: none; padding: 0; display: flex; gap: 4px; }
.cc .cc-steps li { width: 22px; height: 6px; border-radius: 3px; background: var(--cc-line-2); position: relative; }
.cc .cc-steps li span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.cc .cc-steps li.is-key { background: #a8b6cc; }
.cc .cc-steps li.is-done { background: var(--cc-accent); }
.cc .cc-steps li.is-now { background: var(--cc-accent); box-shadow: 0 0 0 2px var(--cc-accent-soft); height: 8px; margin-top: -1px; }

/* layout */
.cc .cc-grid { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: var(--cc-s4); align-items: start; }
.cc .cc-col { display: flex; flex-direction: column; gap: var(--cc-s3); min-width: 0; }
.cc .cc-card { background: var(--cc-surface); border: 1px solid var(--cc-line); border-radius: var(--cc-radius); box-shadow: var(--cc-shadow); padding: 14px var(--cc-s4); }
.cc .cc-h2 { font-size: 17px; font-weight: 700; color: var(--cc-ink); letter-spacing: -0.005em; }
.cc .cc-h3 { font-size: 14px; font-weight: 700; color: var(--cc-ink); margin: var(--cc-s3) 0 var(--cc-s2); }

/* briefing */
.cc .cc-brief { border-left: 4px solid var(--cc-accent); }
.cc .cc-tag { display: inline-block; font-size: 12px; font-weight: 700; color: #1e3a8a; background: var(--cc-accent-soft); border-radius: 999px; padding: 2px 10px; margin-bottom: var(--cc-s2); }
.cc .cc-tag.is-alert { color: #7a2e0e; background: #ffedd5; }
.cc .cc-brief-text { margin-top: 6px; color: var(--cc-ink-2); font-size: 14px; }
.cc .cc-brief-board { margin-top: var(--cc-s2); font-size: 13px; color: var(--cc-muted); }

/* KPIs */
.cc .cc-kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--cc-s2); }
.cc .cc-kpi { background: var(--cc-surface); border: 1px solid var(--cc-line); border-radius: var(--cc-radius-sm); padding: var(--cc-s3); box-shadow: var(--cc-shadow); min-width: 0; }
.cc .cc-kpi-label { font-size: 12px; font-weight: 600; color: var(--cc-muted); }
.cc .cc-kpi-value { font-size: 21px; font-weight: 700; color: var(--cc-ink); font-variant-numeric: tabular-nums; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cc .cc-kpi-sub { font-size: 12px; color: var(--cc-muted); margin-top: 2px; }
.cc .cc-delta { font-weight: 700; font-variant-numeric: tabular-nums; }
.cc .cc-delta.is-up { color: var(--cc-good); }
.cc .cc-delta.is-down { color: var(--cc-bad); }
.cc .cc-delta.is-flat { color: var(--cc-muted); }

/* scorecard */
.cc .cc-score-head { display: flex; align-items: center; gap: var(--cc-s2); flex-wrap: wrap; font-size: 13px; font-weight: 600; color: var(--cc-ink-2); margin-bottom: var(--cc-s2); }
.cc .cc-score-num { font-size: 22px; color: var(--cc-ink); margin-left: auto; font-variant-numeric: tabular-nums; }
.cc .cc-score-num small { font-size: 13px; color: var(--cc-muted); font-weight: 600; }
.cc .cc-score-empty, .cc .cc-score-note { font-size: 12px; color: var(--cc-muted); margin-top: var(--cc-s2); }
.cc .cc-score-cap { font-size: 12px; color: var(--cc-bad); background: var(--cc-bad-soft); border-radius: var(--cc-radius-sm); padding: 6px 10px; margin-top: var(--cc-s2); }
.cc .cc-chip { display: inline-block; font-size: 12px; font-weight: 700; padding: 2px 10px; border-radius: 999px; background: var(--cc-surface-2); border: 1px solid var(--cc-line-2); color: var(--cc-ink-2); }
.cc .cc-chip-exceptional { background: var(--cc-good-soft); border-color: #86efac; color: #14532d; }
.cc .cc-chip-leader { background: #dbeafe; border-color: #93c5fd; color: #1e3a8a; }
.cc .cc-chip-strong { background: #ede9fe; border-color: #c4b5fd; color: #4c1d95; }
.cc .cc-chip-solid { background: var(--cc-warn-soft); border-color: #fcd34d; color: #713f12; }
.cc .cc-chip-needs { background: var(--cc-bad-soft); border-color: #fca5a5; color: #7f1d1d; }
.cc .cc-bar { display: grid; grid-template-columns: 92px 1fr 32px; align-items: center; gap: var(--cc-s2); font-size: 12px; color: var(--cc-ink-2); margin-top: 6px; }
.cc .cc-bar-track { height: 8px; border-radius: 4px; background: var(--cc-line); overflow: hidden; display: block; }
.cc .cc-bar-fill { display: block; height: 100%; border-radius: 4px; }
.cc .cc-bar-fill.is-outcome { background: var(--cc-accent); }
.cc .cc-bar-fill.is-process { background: #0f766e; }
.cc .cc-bar-val { text-align: right; font-weight: 700; font-variant-numeric: tabular-nums; }

/* last quarter */
.cc .cc-result .cc-h3 { margin-top: 0; }
.cc .cc-result-head { font-size: 14px; color: var(--cc-ink-2); }
.cc .cc-why { margin-top: var(--cc-s2); padding-left: 18px; font-size: 13px; color: var(--cc-ink-2); }
.cc .cc-why li { margin: 3px 0; }

/* decisions */
.cc .cc-decisions { display: flex; flex-direction: column; gap: 10px; }
.cc .cc-dec-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--cc-s3); flex-wrap: wrap; }
.cc .cc-dec-note { font-size: 13px; color: var(--cc-muted); }
.cc .cc-group { border: 1px solid var(--cc-line); border-radius: var(--cc-radius-sm); padding: 6px var(--cc-s3) 10px; margin: 0; min-width: 0; }
.cc .cc-group legend { font-size: 12px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--cc-accent); padding: 0 6px; margin: 0; width: auto; border: 0; }
.cc .cc-fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 6px var(--cc-s4); }
.cc .cc-field { min-width: 0; }
.cc .cc-field-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--cc-s2); }
.cc .cc-field label { font-size: 13px; font-weight: 600; color: var(--cc-ink); margin: 0; }
.cc .cc-out { font-size: 14px; font-weight: 700; color: var(--cc-accent); font-variant-numeric: tabular-nums; background: var(--cc-accent-soft); border-radius: 6px; padding: 1px 8px; min-width: 44px; text-align: center; }
.cc .cc-hint { font-size: 12px; color: var(--cc-muted); margin-top: 1px; line-height: 1.35; }
.cc .cc-scale { display: flex; justify-content: space-between; font-size: 11px; color: var(--cc-muted); font-variant-numeric: tabular-nums; margin-top: -2px; }
.cc input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 28px; background: transparent; margin: 0; cursor: pointer; }
.cc input[type=range]::-webkit-slider-runnable-track { height: 6px; border-radius: 3px; background: var(--cc-line-2); }
.cc input[type=range]::-moz-range-track { height: 6px; border-radius: 3px; background: var(--cc-line-2); }
.cc input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 22px; height: 22px; border-radius: 50%; background: var(--cc-accent); border: 3px solid #ffffff; box-shadow: 0 1px 3px rgba(15, 23, 42, 0.35); margin-top: -8px; }
.cc input[type=range]::-moz-range-thumb { width: 18px; height: 18px; border-radius: 50%; background: var(--cc-accent); border: 3px solid #ffffff; box-shadow: 0 1px 3px rgba(15, 23, 42, 0.35); }
.cc input[type=range]:hover::-webkit-slider-thumb { background: #1e40af; }
.cc input[type=range]:focus-visible { outline: none; }
.cc input[type=range]:focus-visible::-webkit-slider-thumb { box-shadow: var(--cc-focus); }
.cc input[type=range]:focus-visible::-moz-range-thumb { box-shadow: var(--cc-focus); }
.cc .cc-select { width: 100%; min-height: 44px; margin-top: 4px; padding: 8px 12px; font-size: 14px; color: var(--cc-ink); background-color: var(--cc-surface); border: 1px solid var(--cc-line-2); border-radius: var(--cc-radius-sm); color-scheme: light; }
.cc .cc-select option { color: var(--cc-ink); background: var(--cc-surface); }
.cc .cc-select:hover { border-color: #94a3b8; }
.cc .cc-select:focus-visible { outline: none; box-shadow: var(--cc-focus); border-color: var(--cc-accent); }
.cc .cc-select:disabled { background: var(--cc-surface-2); color: var(--cc-muted); }
.cc .cc-esg-done { font-size: 13px; color: var(--cc-good); font-weight: 600; align-self: center; }

/* preview and actions */
.cc .cc-preview { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--cc-s2); background: var(--cc-surface-2); border: 1px solid var(--cc-line); border-radius: var(--cc-radius-sm); padding: var(--cc-s2) var(--cc-s3); }
.cc .cc-prev-item { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cc .cc-prev-item span { font-size: 11px; color: var(--cc-muted); line-height: 1.25; }
.cc .cc-prev-item strong { font-size: 15px; font-variant-numeric: tabular-nums; color: var(--cc-ink); }
.cc .cc-prev-item.is-warn strong { color: var(--cc-bad); }
.cc .cc-prev-warn { grid-column: 1 / -1; font-size: 12px; color: var(--cc-warn); background: var(--cc-warn-soft); border-radius: 6px; padding: 6px 10px; }
.cc .cc-validation { font-size: 13px; color: var(--cc-bad); font-weight: 600; min-height: 0; }
.cc .cc-validation:empty { display: none; }
.cc .cc-actions { display: flex; gap: var(--cc-s3); align-items: center; flex-wrap: wrap; }
.cc .cc-btn { min-height: 44px; padding: 10px 20px; font-size: 15px; font-weight: 600; border-radius: var(--cc-radius-sm); cursor: pointer; border: 1px solid transparent; transition: background-color 120ms ease, border-color 120ms ease; }
.cc .cc-btn-primary { background: var(--cc-accent); color: var(--cc-accent-ink); border-color: var(--cc-accent); box-shadow: 0 1px 2px rgba(29, 78, 216, 0.3); }
.cc .cc-btn-primary:hover { background: #1e40af; border-color: #1e40af; }
.cc .cc-btn-primary:disabled, .cc .cc-btn-primary[aria-disabled=true] { background: #94a3b8; border-color: #94a3b8; cursor: not-allowed; box-shadow: none; }
.cc .cc-btn-ghost { background: transparent; color: var(--cc-ink-2); border-color: var(--cc-line-2); font-size: 14px; }
.cc .cc-btn-ghost:hover { background: var(--cc-surface-2); border-color: #94a3b8; }
.cc .cc-btn:focus-visible { outline: none; box-shadow: var(--cc-focus); }

/* debrief */
.cc .cc-debrief-head { display: flex; flex-direction: column; gap: 4px; }
.cc .cc-debrief-score { font-size: 13px; display: flex; align-items: center; gap: var(--cc-s2); margin-top: var(--cc-s2); }
.cc .cc-debrief-score strong { font-size: 40px; line-height: 1; font-weight: 800; color: var(--cc-ink); font-variant-numeric: tabular-nums; }
.cc .cc-debrief-score small { font-size: 15px; color: var(--cc-muted); font-weight: 600; margin-left: -6px; }
.cc .cc-debrief-sub { font-size: 13px; color: var(--cc-muted); }
.cc .cc-dkpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: var(--cc-s2); margin-top: var(--cc-s3); }
.cc .cc-dkpi { background: var(--cc-surface-2); border: 1px solid var(--cc-line); border-radius: var(--cc-radius-sm); padding: var(--cc-s2) var(--cc-s3); display: flex; flex-direction: column; gap: 2px; }
.cc .cc-dkpi span { font-size: 11px; color: var(--cc-muted); }
.cc .cc-dkpi strong { font-size: 15px; font-variant-numeric: tabular-nums; }
.cc .cc-turning { font-size: 14px; color: var(--cc-ink); background: #fff7ed; border-left: 4px solid #c2410c; border-radius: 6px; padding: var(--cc-s3); }
.cc .cc-insights, .cc .cc-questions { padding-left: 20px; font-size: 14px; color: var(--cc-ink-2); }
.cc .cc-insights li, .cc .cc-questions li { margin: 6px 0; }

/* details */
.cc .cc-details { margin-top: var(--cc-s4); }
.cc .cc-details > summary { cursor: pointer; font-weight: 700; font-size: 14px; color: var(--cc-ink); min-height: 32px; display: flex; align-items: center; list-style-position: inside; }
.cc .cc-details > summary:focus-visible { outline: none; box-shadow: var(--cc-focus); border-radius: 6px; }
.cc .cc-charts { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: var(--cc-s4); margin-top: var(--cc-s3); }
.cc .cc-chart { min-width: 0; }
.cc .cc-chart-box { position: relative; height: 280px; width: 100%; }
.cc .cc-chart-alt { font-size: 12px; color: var(--cc-muted); margin-top: var(--cc-s2); }
.cc .cc-table-wrap { overflow-x: auto; border: 1px solid var(--cc-line); border-radius: var(--cc-radius-sm); }
.cc .cc-table-wrap:focus-visible { outline: none; box-shadow: var(--cc-focus); }
.cc .cc-table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }
.cc .cc-table th { text-align: right; font-weight: 600; color: var(--cc-muted); background: var(--cc-surface-2); padding: 8px 10px; border-bottom: 1px solid var(--cc-line); white-space: nowrap; }
.cc .cc-table td { text-align: right; padding: 7px 10px; border-bottom: 1px solid var(--cc-line); white-space: nowrap; color: var(--cc-ink-2); }
.cc .cc-table th:first-child, .cc .cc-table td:first-child { text-align: left; }
.cc .cc-glossary { display: grid; grid-template-columns: minmax(140px, 220px) 1fr; gap: 6px var(--cc-s4); font-size: 13px; }
.cc .cc-glossary dt { font-weight: 700; color: var(--cc-ink); }
.cc .cc-glossary dd { margin: 0; color: var(--cc-ink-2); }

/* responsive */
@media (max-width: 1100px) {
    .cc .cc-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 640px) {
    .capstone-sim-container.cc { padding: var(--cc-s3); font-size: 14px; }
    .cc .cc-top { align-items: flex-start; }
    .cc .cc-progress { align-items: flex-start; }
    .cc .cc-counter { justify-content: flex-start; }
    .cc .cc-steps li { width: 16px; }
    .cc .cc-preview { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cc .cc-fields { grid-template-columns: minmax(0, 1fr); }
    .cc .cc-actions .cc-btn { flex: 1 1 100%; }
    .cc .cc-glossary { grid-template-columns: minmax(0, 1fr); }
    .cc .cc-charts { grid-template-columns: minmax(0, 1fr); }
    .cc .cc-kpi-value { font-size: 18px; }
}
@media (prefers-reduced-motion: reduce) {
    .cc *, .cc *::before, .cc *::after { transition: none !important; animation: none !important; }
}

