            var sc = CCModel.score(ds, Math.max(1, L.length));
            var tsr = sc.tsr;
            var avg = function (k, from, to) { var t = 0, n = 0; for (var i = 0; i < L.length; i++) { if (L[i].q >= from && L[i].q <= to) { t += L[i][k]; n++; } } return n ? t / n : 0; };
            var q7 = null; for (var i = 0; i < L.length; i++) { if (L[i].q === 7) { q7 = L[i]; } }
            var entered = ds.markets || {};
            var nEntered = 0, early = 0; for (var k in entered) { if (Object.prototype.hasOwnProperty.call(entered, k)) { nEntered++; if (entered[k].since <= 3) { early++; } } }
            var avgMk = avg('marketing', 1, 12), avgRd = avg('rd', 1, 12);

            if (ds.warResponse === 'matched') {
                ins.push({ q: 7, w: 10, id: 'matched', text: self._t('ins_matched', { p: q7 ? q7.price : '', rp: 87 }) });
            } else if (ds.warResponse === 'held' && q7) {
                ins.push({ q: 7, w: 5, id: 'held', text: self._t(q7.marketing >= 22 || q7.rd >= 14 ? 'ins_held_invest' : 'ins_held', { p: q7.price, mk: q7.marketing, rd: q7.rd }) });
            } else if (ds.warResponse === 'partial' && q7) {
                ins.push({ q: 7, w: 6, id: 'partial', text: self._t('ins_partial', { p: q7.price }) });
            }
            if (ds.discountQuarters >= 4) {
                var dq0 = null, dsum = 0, dn = 0;
                for (var di = 0; di < L.length; di++) { if (L[di].price < 96) { if (dq0 === null) { dq0 = L[di].q; } dsum += L[di].price; dn++; } }
                ins.push({ q: dq0 || 1, w: 7, id: 'discount', text: self._t('ins_discount', { n: ds.discountQuarters, p: self._num(dn ? dsum / dn : 0, 0) }) });
            }
            if (ds.stockoutQuarters > 0) {
                ins.push({ q: ds.stockouts[0], w: 9, id: 'stockout', text: self._t('ins_stockout', { n: ds.stockoutQuarters, q: ds.stockouts.join(', ') }) });
            }
            if (ds.breachQuarters > 0) {
                ins.push({ q: ds.flags.firstBreach || 1, w: 8, id: 'breach', text: self._t('ins_breach', { n: ds.breachQuarters, q: ds.flags.firstBreach, peak: self._money(ds.revolverPeak || 0, 0) }) });
            }
            if (ds.esgFines > 0) {
                ins.push({ q: ds.fines[0], w: 8, id: 'esg', text: self._t('ins_esg_fines', { n: ds.esgFines, cost: self._money(ds.esgFines * 5, 0) }) });
            } else if (ds.esgCompliant) {
                ins.push({ q: 9, w: 2, id: 'esgok', text: self._t('ins_esg_ok') });
            }
            if (avgMk <= 11 || avgRd <= 5) {
                ins.push({ q: 1, w: 9, id: 'harvest', text: self._t('ins_harvest', { mk: self._num(avgMk, 0), rd: self._num(avgRd, 0), b: self._num(ds.brand, 0), i: self._num(ds.innovation, 0) }) });
            } else if (ds.brand + ds.innovation >= 100) {
                ins.push({ q: 12, w: 4, id: 'assets', text: self._t('ins_assets', { b: self._num(ds.brand, 0), i: self._num(ds.innovation, 0) }) });
            }
            if (early >= 2 || nEntered >= 3 && avg('price', 1, 4) <= 90) {
                ins.push({ q: 3, w: 9, id: 'overreach', text: self._t('ins_overreach', { n: nEntered }) });
            }
            if (ds.flags.lateAndina) {
                ins.push({ q: ds.flags.lateAndina, w: 6, id: 'late', text: self._t('ins_late_andina', { q: ds.flags.lateAndina }) });
            }
            if (entered.sur && (entered.sur.share < 2)) {
                ins.push({ q: entered.sur.since, w: 5, id: 'austral', text: self._t('ins_austral_fit', { i: self._num(ds.innovation, 0) }) });
            }
            if (nEntered === 0 && L.length >= 10) {
                ins.push({ q: 10, w: 6, id: 'single', text: self._t('ins_single_market') });
            }
            if (L.length >= 12) {
                var l12 = L[11], prev = 0, n = 0;
                for (var j = 7; j < 11; j++) { if (L[j]) { prev += L[j].marketing + L[j].rd; n++; } }
                if (n && (l12.marketing + l12.rd) < 0.8 * prev / n) { ins.push({ q: 12, w: 5, id: 'endcut', text: self._t('ins_end_cut') }); }
            }
            if (ds.stockoutQuarters === 0 && L.length >= 4) {
                var ut = ds.utilHistory || [], us = 0; for (var u = 0; u < ut.length; u++) { us += ut[u]; }
                ins.push({ q: 12, w: 3, id: 'capok', text: self._t('ins_capacity_ok', { u: self._num(ut.length ? us / ut.length : 0, 0) }) });
            }
            if (nEntered > 0 && ds.lastResults && ds.lastResults.revenue > 0) {
                var lr = ds.lastResults;
                ins.push({ q: 12, w: 3, id: 'intl', text: self._t('ins_intl', { v: self._money(lr.intlRevenue), p: self._num(lr.intlRevenue / lr.revenue * 100, 0), list: (lr.intl || []).map(function (m) { return self._t('mk_' + m.key) + ' ' + self._pct(m.share); }).join(', ') }) });
            }
            var payout = sc.avgPayout;
            if (payout >= 10 && payout <= 35) { ins.push({ q: 12, w: 2, id: 'payok', text: self._t('ins_payout_ok', { p: self._num(payout, 0) }) }); }
            if (payout < 10) { var nq = 1; for (var ni0 = 0; ni0 < L.length; ni0++) { if (L[ni0].dividend < 10) { nq = L[ni0].q; break; } } ins.push({ q: nq, w: 6, id: 'nodiv', text: self._t('ins_low_payout', { p: self._num(payout, 0) }) }); }
            else if (payout > 35) { ins.push({ q: 1, w: 4, id: 'highdiv', text: self._t('ins_high_payout', { p: self._num(payout, 0) }) }); }
            if (!ins.length) { ins.push({ q: 12, w: 1, id: 'steady', text: self._t('ins_steady') }); }
            ins.sort(function (a, b) { return b.w - a.w; });
            var top = ins.slice(0, 5);

            /* turning point: the quarter where the scorecard fell most, explained by what was decided or hit then */
            var drop = 0, dq = null;
            for (var t = 1; t < sh.length; t++) { if (sh[t - 1] - sh[t] > drop) { drop = sh[t - 1] - sh[t]; dq = t + 1; } }
            var cause = null;
            for (var c = 0; c < ins.length; c++) { if (ins[c].w >= 6 && (dq === null || Math.abs(ins[c].q - dq) <= 1)) { cause = ins[c]; break; } }
            if (!cause) { for (var c2 = 0; c2 < ins.length; c2++) { if (ins[c2].w >= 6) { cause = ins[c2]; break; } } }
            var turning;
            if (cause) {
                turning = self._t('tp_' + cause.id, { q: cause.q, from: dq && sh[dq - 2] != null ? sh[dq - 2] : '', to: dq ? sh[dq - 1] : '' });
                if (turning === 'tp_' + cause.id) { turning = self._t('tp_generic', { q: dq || cause.q }); }
            } else if (dq && drop >= 6 && sh.length >= 12 && sh[sh.length - 1] >= 68) {
                turning = self._t('tp_recovered', { q: dq, from: sh[dq - 2], to: sh[dq - 1], ev: self._evName(dq), end: sh[sh.length - 1] });
            } else if (dq && drop >= 6) {
                turning = self._t('tp_event', { q: dq, from: sh[dq - 2], to: sh[dq - 1], ev: self._evName(dq) });
            } else {
                turning = self._t('tp_none');
            }
            return { insights: top, all: ins, turning: turning, tsr: tsr, score: sc };
        }

        /* ---------- rendering ---------- */
        _state() { return window.mySimulation && window.mySimulation.state; }
        _runOver(st) {
            try { if (window.mySimulation && typeof window.mySimulation.isRunComplete === 'function') { return !!window.mySimulation.isRunComplete(); } } catch (e) {}
            var maxP = (st && st.maxPeriods) || 12;
            if (st && st.currentPeriod > maxP) { return true; }
            var h = (st && st.history) || (window.mySimulation && window.mySimulation.history) || [];
            return h.length >= maxP;
        }

        _bind() {
            if (this._bound) { return; }
            this._bound = true;
            var self = this;
            var ids = ['priceInput', 'marketingInput', 'rdInput', 'salesInput', 'capexInput', 'dividendInput', 'expansionInput', 'esgInput'];
            ids.forEach(function (id) {
                var el = document.getElementById(id);
                if (!el) { return; }
                var h = function () { try { self._paintOutputs(); self._paintPreview(); var v = self._el('ccValidation'); if (v) { v.textContent = ''; } } catch (e) {} };
                el.addEventListener('input', h);
                el.addEventListener('change', h);
            });
            document.addEventListener('express:langchanged', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
            var f = window.mySimulation;
            if (f && f.eventBus && typeof f.eventBus.on === 'function') {
                f.eventBus.on('language:changed', function () { try { self._render(); self._paintCharts(); } catch (e) {} });
                f.eventBus.on('period:submitted', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('period:undone', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('state:loaded', function () { try { self._render(); } catch (e) {} });
                f.eventBus.on('simulation:complete', function () { try { self._render(); } catch (e) {} });
            }
        }

        _render() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState;
            var over = this._runOver(st);
            var q = over ? (st.history ? st.history.length : 12) : (st.currentPeriod || 1);
            this._paintStatic();
            this._paintSteps(q, over);
            this._paintBriefing(q, over);
            this._paintKpis(ds);
            this._paintScore(ds);
            this._paintResult(st);
            this._paintOptions(ds, q);
            this._paintOutputs();
            this._paintPreview();
            this._paintChartAlt(ds);
            var form = this._el('ccForm'), deb = this._el('debriefPanel');
            if (over) {
                if (form) { form.hidden = true; }
                if (deb) { deb.innerHTML = this._debriefHTML(ds, this.getPerformanceSummary(st.history)); deb.hidden = false; }
            } else {
                if (form) { form.hidden = false; }
                if (deb) { deb.hidden = true; deb.innerHTML = ''; }
            }
            try { document.documentElement.lang = this._lang(); } catch (e) {}
        }

        _paintStatic() {
            var g = this._el('ccGlossary');
            if (g) {
                var terms = ['price_index', 'brand', 'innovation', 'capacity', 'eps', 'tsr', 'ceiling', 'scorecard'];
                var html = '';
                for (var i = 0; i < terms.length; i++) { html += '<dt>' + this._t('g_' + terms[i]) + '</dt><dd>' + this._t('g_' + terms[i] + '_d') + '</dd>'; }
                this._set('ccGlossary', html);
            }
        }

        _paintSteps(q, over) {
            var ol = this._el('ccSteps');
            if (ol) {
                var html = '';
                for (var i = 1; i <= 12; i++) {
                    var cls = (i < q || (over && i <= q)) ? 'is-done' : (i === q ? 'is-now' : '');
                    if ([2, 7, 9].indexOf(i) >= 0) { cls += ' is-key'; }
                    html += '<li class="' + cls + '"><span>' + i + '</span></li>';
                }
                this._set('ccSteps', html);
            }
            var yr = this._el('ccYear');
            if (yr) { yr.textContent = over ? this._t('run_complete') : this._t('year_label', { y: Math.ceil(q / 4), qq: ((q - 1) % 4) + 1, cal: 2026 + Math.floor((q - 1) / 4) }); }
        }

        _paintBriefing(q, over) {
            this._set('ccEventTag', over ? this._t('tag_done') : this._t(CC_EVENT_TAG[q] || 'tag_1'));
            this._set('ccBriefTitle', over ? this._t('brief_done_title') : this._t('brief_title_' + q));
            this._set('briefingText', over ? this._t('brief_done') : this._t('brief_' + q));
            var note = '';
            if (!over) {
                if (q <= 7) { note = this._t('board_window', { n: 7 - q + 1 }); }
                else { note = this._t('board_note'); }
            }
            this._set('ccBoardNote', note);
            var tag = this._el('ccEventTag');
            if (tag) { tag.className = 'cc-tag' + ([3, 5, 7, 8, 9, 11].indexOf(q) >= 0 && !over ? ' is-alert' : ''); }
        }

        _delta(arr, dec, unit) {
            if (!arr || arr.length < 2) { return ''; }
            var d = arr[arr.length - 1] - arr[arr.length - 2];
            var cls = d > 0.05 ? 'is-up' : (d < -0.05 ? 'is-down' : 'is-flat');
            return '<span class="cc-delta ' + cls + '">' + (d > 0.05 ? '▲ ' : d < -0.05 ? '▼ ' : '') + this._signed(d, dec, unit) + '</span> ' + this._t('vs_prev');
        }

        _paintKpis(ds) {
            var hasRun = (ds.revenueHistory || []).length > 0;
            var debt = CCModel.M.debtCeiling + (ds.revolver || 0);
            this._set('cashDisplay', this._money(ds.cash));
            this._set('cashSub', '<span class="' + (ds.revolver > 0.5 ? 'cc-bad' : '') + '">' + this._t('debt_sub', { d: this._money(debt, 0), c: this._money(CCModel.M.debtCeiling, 0) }) + '</span>');
            this._set('shareDisplay', this._pct(ds.centralShare));
            this._set('shareSub', hasRun ? this._delta(ds.shareHistory, 1, this._lang() === 'es' ? ' pp' : ' pts') : this._t('start_sub'));
            var ni = hasRun ? ds.netIncomeHistory[ds.netIncomeHistory.length - 1] : null;
            this._set('netIncomeDisplay', ni === null ? '—' : '<span class="' + (ni < 0 ? 'cc-bad' : '') + '">' + this._money(ni) + '</span>');
            this._set('netIncomeSub', hasRun ? this._t('cum_sub', { v: this._money(ds.cumNI) }) : this._t('ni_start'));
            this._set('sharePriceDisplay', this._usd(ds.sharePrice));
            var tsr = ((ds.sharePrice || 0) + (ds.cumDividends || 0) / CCModel.M.shares - CCModel.M.p0) / CCModel.M.p0 * 100;
            this._set('sharePriceSub', hasRun ? this._t('tsr_sub', { v: this._signed(tsr, 0, this._lang() === 'es' ? ' %' : '%') }) : this._t('price_start'));
        }

        _paintScore(ds) {
            var p = ds.performance;
            if (!p) {
                this._set('ccScoreCard', '<p class="cc-score-head"><span>' + this._t('scorecard') + '</span></p><p class="cc-score-empty">' + this._t('scorecard_empty') + '</p>');
                return;
            }
            var bar = function (label, v, cls) {
                return '<div class="cc-bar"><span class="cc-bar-label">' + label + '</span><span class="cc-bar-track" role="img" aria-label="' + label + ' ' + v + '/100"><span class="cc-bar-fill ' + cls + '" style="width:' + Math.max(2, v) + '%"></span></span><span class="cc-bar-val">' + v + '</span></div>';
            };
            var html = '<p class="cc-score-head"><span>' + this._t('scorecard') + '</span>' +
                '<strong class="cc-score-num">' + p.overallScore + '<small>/100</small></strong>' +
                '<span class="cc-chip cc-chip-' + p.tier + '">' + this._t('perf_' + p.tier) + '</span></p>' +
                bar(this._t('sub_outcome'), p.outcome, 'is-outcome') + bar(this._t('sub_process'), p.process, 'is-process') +
                (p.cap ? '<p class="cc-score-cap">' + this._t('cap_' + p.cap) + '</p>' : '<p class="cc-score-note">' + this._t('scorecard_note') + '</p>');
            this._set('ccScoreCard', html);
        }

        _paintResult(st) {
            var ds = st.domainState, r = ds.lastResults;
            if (!r) {
                this._set('ccResultPanel', '<h3 class="cc-h3" id="ccResultTitle">' + this._t('result_title_none') + '</h3><p class="cc-muted">' + this._t('result_none') + '</p>');
                return;
            }
            var self = this, lines = [];
            var rev = ds.revenueHistory, prevRev = rev.length > 1 ? rev[rev.length - 2] : 121;
            lines.push(self._t('r_price', { p: r.price, rp: self._num(r.rivalPrice, 0), e: self._num(r.elasticity, 2) }));
            if (r.fill < 97) { lines.push('<span class="cc-bad">' + self._t('r_stockout', { f: 100 - r.fill }) + '</span>'); }
            else { lines.push(self._t('r_util', { u: r.utilization })); }
            lines.push(self._t('r_assets', { b: self._num(r.brand, 0), i: self._num(r.innovation, 0) }));
            if (r.intl && r.intl.length) {
                lines.push(self._t('r_intl', { v: self._money(r.intlRevenue), list: r.intl.map(function (m) { return self._t('mk_' + m.key) + ' ' + self._pct(m.share); }).join(' · ') }));
            }
            if (r.drew > 0) { lines.push('<span class="cc-bad">' + self._t('r_borrow', { v: self._money(r.drew, 0), d: self._money(r.debt, 0) }) + '</span>'); }
            if (r.divSignal > 0) { lines.push('<span class="cc-bad">' + self._t('r_divsignal', { v: self._num(r.divSignal, 1) }) + '</span>'); }
            if (r.esgCost === 5) { lines.push('<span class="cc-bad">' + self._t('r_fine') + '</span>'); }
            if (r.period === 7 || r.period === 8) {
                if (ds.warState === 'escalated') { lines.push('<span class="cc-bad">' + self._t('r_war_escalated') + '</span>'); }
                else { lines.push(self._t('r_war_holding')); }
            }
            var html = '<h3 class="cc-h3" id="ccResultTitle">' + self._t('result_title', { q: r.period }) + '</h3>' +
                '<p class="cc-result-head">' + self._t('r_head', {
                    rev: '<strong>' + self._money(r.revenue) + '</strong>', d: self._signed((r.revenue / prevRev - 1) * 100, 0, '%'),
                    ni: '<strong class="' + (r.netIncome < 0 ? 'cc-bad' : '') + '">' + self._money(r.netIncome) + '</strong>',
                    gm: self._pct(r.grossMargin)
                }) + '</p><ul class="cc-why">';
            for (var i = 0; i < lines.length; i++) { html += '<li>' + lines[i] + '</li>'; }
            html += '</ul>';
            this._set('ccResultPanel', html);
        }

        _paintOptions(ds, q) {
            var M = CCModel.M, self = this;
            var setOpt = function (id, key) {
                var o = self._el(id);
                if (!o) { return; }
                var entered = ds.markets && ds.markets[key];
                var closed = key === 'andina' && q < M.markets.andina.open;
                var label = entered ? self._t('opt_entered', { m: self._t('mk_' + key) }) :
                    closed ? self._t('opt_closed', { m: self._t('mk_' + key) }) :
                    self._t('opt_enter', { m: self._t('mk_' + key), c: self._money(CCModel.entryCost(key, q), 0) }) + (key === 'andina' && q > M.markets.andina.closeAfter ? ' · ' + self._t('opt_late') : '');
                if (o.textContent !== label) { o.textContent = label; }
                o.disabled = !!(entered || closed);
            };
            setOpt('optAndina', 'andina'); setOpt('optSur', 'sur'); setOpt('optNorte', 'norte');
            this._set('expansionHint', this._t('expansion_hint'));
            var sel = this._el('expansionInput');
            if (sel && sel.selectedIndex >= 0 && sel.options[sel.selectedIndex] && sel.options[sel.selectedIndex].disabled) { sel.value = ''; }
            var esgF = this._el('esgField'), done = this._el('esgDone');
            var showEsg = q >= 9 && !ds.esgCompliant && !this._runOver(this._state());
            if (esgF) { esgF.hidden = !showEsg; }
            if (done) {
                done.hidden = !(q >= 9 && ds.esgCompliant);
                done.textContent = ds.esgCompliant ? this._t('esg_done') : '';
            }
            this._set('salesHint', this._t('sales_hint', { n: this._num(ds.salesForce, 0) }));
        }

        _val(id) { var e = this._el(id); return e ? parseFloat(e.value) : 0; }

        _paintOutputs() {
            var es = this._lang() === 'es';
            var setOut = function (id, txt) { var o = document.getElementById(id); if (o && o.textContent !== txt) { o.textContent = txt; } };
            setOut('priceOut', String(this._val('priceInput')));
            setOut('marketingOut', this._money(this._val('marketingInput'), 0));
            setOut('rdOut', this._money(this._val('rdInput'), 0));
            var s = this._val('salesInput');
            setOut('salesOut', (s > 0 ? '+' : '') + this._num(s, 0));
            setOut('capexOut', this._money(this._val('capexInput'), 0));
            setOut('dividendOut', this._num(this._val('dividendInput'), 0) + (es ? ' %' : '%'));
        }

        _paintPreview() {
            var st = this._state();
            if (!st || !st.domainState) { return; }
            var ds = st.domainState, q = st.currentPeriod || 1, M = CCModel.M;
            if (this._runOver(st)) { this._set('ccPreview', ''); return; }
            var mk = this._val('marketingInput'), rd = this._val('rdInput'), s = this._val('salesInput'), cx = this._val('capexInput');
            var sf = Math.max(100, Math.min(1200, ds.salesForce + s));
            var ex = (this._el('expansionInput') || {}).value || '';
            var entry = (ex && ex !== 'none' && !(ds.markets && ds.markets[ex])) ? CCModel.entryCost(ex, q) : 0;
            var esgSel = (this._el('esgInput') || {}).value || '';
            var esg = q >= 9 && (ds.esgCompliant || esgSel === 'comply') ? 2 : 0;
            var opex = mk + rd + 0.022 * sf + 0.01 * Math.max(0, s) + 0.012 * Math.max(0, -s) + esg;
            var invest = cx + entry;
            var cushion = ds.cash - invest;
            var capNext = ds.capacity + ds.pendingTons + Math.round(cx * M.tonsPerMillion);
            var warn = cushion < 10;
            var html = '<div class="cc-prev-item"><span>' + this._t('pv_opex') + '</span><strong>' + this._money(opex) + '</strong></div>' +
                '<div class="cc-prev-item"><span>' + this._t('pv_invest') + '</span><strong>' + this._money(invest) + '</strong></div>' +
                '<div class="cc-prev-item' + (warn ? ' is-warn' : '') + '"><span>' + this._t('pv_cash') + '</span><strong>' + this._money(cushion) + '</strong></div>' +
                '<div class="cc-prev-item"><span>' + this._t('pv_capacity') + '</span><strong>' + this._num(capNext / 1000, 0) + (this._lang() === 'es' ? ' mil t' : 'k t') + '</strong></div>' +
                (warn ? '<p class="cc-prev-warn">' + this._t('pv_warn') + '</p>' : '');
            this._set('ccPreview', html);
        }

        _paintChartAlt(ds) {
            var rev = ds.revenueHistory || [], ni = ds.netIncomeHistory || [], sh = ds.shareHistory || [], pr = ds.sharePriceHistory || [];
            var a1 = rev.length ? this._t('alt_rev', { n: rev.length, r0: this._money(rev[0]), r1: this._money(rev[rev.length - 1]), lo: this._money(Math.min.apply(null, ni)), hi: this._money(Math.max.apply(null, ni)) }) : this._t('alt_empty');
            var a2 = sh.length ? this._t('alt_share', { s0: this._pct(sh[0]), s1: this._pct(sh[sh.length - 1]), p1: this._usd(pr[pr.length - 1]) }) : this._t('alt_empty');
            this._set('revenueChartAlt', a1);
            this._set('shareChartAlt', a2);
            var c1 = this._el('revenueChart'), c2 = this._el('shareChart');
            if (c1) { c1.setAttribute('aria-label', this._t('chart_rev_title')); }
            if (c2) { c2.setAttribute('aria-label', this._t('chart_share_title')); }
        }

        _paintCharts() {
            var ui = window.mySimulation && window.mySimulation.uiManager;
            if (!ui || !ui.charts) { return; }
            var cfg = this.getChartConfig();
            for (var id in cfg) {
                if (!Object.prototype.hasOwnProperty.call(cfg, id)) { continue; }
                var ch = ui.charts[id];
                if (!ch || !ch.data || !ch.options) { continue; }
                try {
                    for (var k = 0; k < cfg[id].data.datasets.length; k++) { if (ch.data.datasets[k]) { ch.data.datasets[k].label = cfg[id].data.datasets[k].label; } }
                    if (ch.options.plugins && ch.options.plugins.title) { ch.options.plugins.title.text = cfg[id].options.plugins.title.text; }
                    for (var ax in cfg[id].options.scales) {
                        if (ch.options.scales && ch.options.scales[ax] && ch.options.scales[ax].title && cfg[id].options.scales[ax].title) { ch.options.scales[ax].title.text = cfg[id].options.scales[ax].title.text; }
                    }
                    var st = this._state();
                    if (st) { var dd = this.getChartData(st)[id]; if (dd) { ch.data.labels = dd.labels; } }
                    ch.update('none');
                } catch (e) {}
            }
        }

        _debriefHTML(ds, summary) {
            var self = this;
            summary = summary || {};
            var a = this._analyse(ds);
            var p = ds.performance || {};
            var s = typeof p.overallScore === 'number' ? p.overallScore : (summary.overallScore || 0);
            var tier = p.tier || CCModel.tier(s);
            var r = ds.lastResults || {};
            var kpi = function (label, val) { return '<div class="cc-dkpi"><span>' + label + '</span><strong>' + val + '</strong></div>'; };
            var html = '<div class="cc-debrief-head"><p class="cc-kicker">' + self._t('debrief_kicker') + '</p>' +
                '<h2 class="cc-h2" id="ccDebriefTitle">' + self._t('debrief_title') + '</h2>' +
                '<p class="cc-debrief-score"><strong>' + s + '</strong><small>/100</small> <span class="cc-chip cc-chip-' + tier + '">' + self._t('perf_' + tier) + '</span></p>' +
                '<p class="cc-debrief-sub">' + self._t('debrief_sub', { o: p.outcome != null ? p.outcome : '—', g: p.process != null ? p.process : '—' }) + '</p></div>';
            html += '<div class="cc-dkpis">' +
                kpi(self._t('k_revenue'), self._money(r.revenue)) +
                kpi(self._t('k_cumni'), self._money(ds.cumNI)) +
                kpi(self._t('k_tsr'), self._signed((a.tsr || 0) * 100, 0, '%')) +
                kpi(self._t('k_share'), self._pct(ds.centralShare)) +
                kpi(self._t('k_assets'), self._num(ds.brand, 0) + ' + ' + self._num(ds.innovation, 0)) +
                kpi(self._t('k_markets'), String(r.marketsActive || 1)) +
                kpi(self._t('k_debt'), self._money(CCModel.M.debtCeiling + (ds.revolver || 0), 0)) + '</div>';
            if (p.cap) { html += '<p class="cc-score-cap">' + self._t('cap_' + p.cap) + '</p>'; }
            html += '<h3 class="cc-h3">' + self._t('turning_title') + '</h3><p class="cc-turning">' + a.turning + '</p>';
            html += '<h3 class="cc-h3">' + self._t('insights_title') + '</h3><ul class="cc-insights">';
            for (var i = 0; i < a.insights.length; i++) { html += '<li>' + a.insights[i].text + '</li>'; }
            html += '</ul><h3 class="cc-h3">' + self._t('questions_title') + '</h3><ol class="cc-questions">' +
                '<li>' + self._t('dq1', { w: ds.warResponse ? self._t('war_' + ds.warResponse) : self._t('war_none') }) + '</li>' +
                '<li>' + self._t('dq2') + '</li>' +
                '<li>' + self._t('dq3', { rev: self._money(r.revenue), ni: self._money(ds.cumNI), s: s }) + '</li></ol>';
            return '<div class="cc-debrief-body">' + html + '</div>';
        }

